package com.jtech.controller;
import com.jtech.entity.*; import com.jtech.dto.response.*; import com.jtech.repository.CourseRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/courses") public class CourseController { private final CourseRepository repository; public CourseController(CourseRepository repository){this.repository=repository;} @GetMapping public List<CourseSummary> getCourses(){return repository.findByStatusOrderByDisplayOrderAscIdAsc(Course.Status.PUBLISHED).stream().map(c->new CourseSummary(c.getId(),c.getCode(),c.getName(),c.getDescription(),c.getThumbnailUrl(),c.getChapters().stream().filter(ch->ch.getStatus()==Course.Status.PUBLISHED).count())).toList();} @GetMapping("/{id}") public ResponseEntity<CourseDetail> getCourse(@PathVariable Long id){return repository.findByIdAndStatus(id, Course.Status.PUBLISHED).map(c->ResponseEntity.ok(new CourseDetail(c.getId(),c.getCode(),c.getName(),c.getDescription(),c.getThumbnailUrl(),c.getChapters().stream().filter(ch->ch.getStatus()==Course.Status.PUBLISHED).map(ch->new ChapterSummary(ch.getId(),ch.getChapterNo(),ch.getTitle(),ch.getDescription())).toList()))).orElseGet(()->ResponseEntity.notFound().build());} }


